var deptId = V8.ThisValue;
if(!deptId){
  V8.FormSet('DeptCode', '');
  return;
}
var data = V8.Field.DeptId.Data;
var findModel = V8.DiyCommon.ArrayDeepSearch(data, '_Child', 'Id', deptId);

if(findModel){
  V8.FormSet('DeptCode', findModel.Code);
  V8.FormSet('DeptName', findModel.Name);
  
  var isSetedCompany = false;
  var findCompany = {...findModel};//{ ParentId : findModel.ParentId};
  while(findCompany){
    if(findCompany && findCompany.IsCompany){
        V8.FormSet('CompanyCode', findCompany.Code);
        V8.FormSet('CompanyName', findCompany.Name);
        V8.FormSet('CompanyId', findCompany.Id);
        isSetedCompany = true;
        break;
    }
    findCompany = V8.DiyCommon.ArrayDeepSearch(data, '_Child', 'Id', findCompany.ParentId);
  }
  if(!isSetedCompany){
    V8.FormSet('CompanyCode', '');
    V8.FormSet('CompanyName', '');
    V8.FormSet('CompanyId', '');
  }
}

