// v1.0.0 仅在用户主动点击下载时签发私有临时地址。
if(!V8.CurrentUser || !V8.CurrentUser.Id || Number(V8.CurrentUser.Level || 0) < 9999){
  return { Code:0, Msg:'仅 iTdos 超级管理员可下载数据库备份。' };
}
var backup = V8.FormEngine.GetFormData('mci_database_backup', {
  Id: V8.Param.RecordId,
  _SelectFields:['Id','FileName','HdfsPath','Status','RetentionStatus']
});
if(backup.Code != 1){ return { Code:0, Msg:'备份记录不存在。' }; }
if(!backup.Data.HdfsPath || backup.Data.RetentionStatus == 'Deleted'){
  return { Code:0, Msg:'备份文件已按保留策略清理，无法下载。' };
}
var fileResult = V8.Method.GetPrivateFileUrl({
  FilePathName: backup.Data.HdfsPath,
  Limit: true,
  OsClient: V8.OsClient
});
if(!fileResult || fileResult.Code != 1){ return fileResult || {Code:0,Msg:'生成私有下载地址失败。'}; }
return { Code:1, Data:{ FileName:backup.Data.FileName, Url:fileResult.Data }, Msg:'私有下载地址已生成。' };

