/*
 * V8 ApiEngine
 * ApiEngineKey: admin_build_sanitized_empty_database
 * Version: v1.0.9
 * Function:
 * - 仅允许 iTdos 超级管理员通过可续跑后台任务制作主库脱敏空数据库；分阶段执行 Prepare、Sanitize、Publish 并持久化 Checkpoint；宿主按表使用独立连接、事务内幂等复制、传输异常有限重试和 Redis 所有者租约；检查点片段立即续跑，校验仅保留吾码内置 microi-platform-service 后发布多数据库空库到 HDFS。
 */

function text(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function report(current, message) {
  if (!backgroundTaskId || !V8.Method || typeof V8.Method.UpdateBackgroundTask !== "function") return;
  V8.Method.UpdateBackgroundTask({
    _BackgroundTaskId: backgroundTaskId,
    Current: current,
    Total: 8,
    Progress: Math.floor(current * 100 / 8),
    Msg: message,
    Message: message
  });
}

function cleanup() {
  try {
    if (V8.Method && typeof V8.Method.CleanupEmptyDatabaseRelease === "function") {
      return V8.Method.CleanupEmptyDatabaseRelease(baseParam);
    }
  } catch (cleanupEx) {
    console.error("CleanupEmptyDatabaseRelease", cleanupEx && cleanupEx.message ? cleanupEx.message : cleanupEx);
  }
  return null;
}

function fail(message, data, needCleanup) {
  if (needCleanup) cleanup();
  report(0, message);
  return {
    Code: 0,
    Msg: message,
    Data: data || null
  };
}

function continueWith(checkpoint, current, message, dataAppend) {
  report(current, message);
  return {
    Code: 1,
    Msg: message,
    Data: {
      BackgroundTask: {
        HasMore: true,
        Checkpoint: checkpoint,
        Current: current,
        Total: 8,
        NextDelaySeconds: 0,
        Msg: message
      }
    },
    DataAppend: dataAppend || {}
  };
}

function audit(title, content, level) {
  try {
    V8.Method.AddSysLog({
      Type: "安全审计",
      Title: title,
      Content: JSON.stringify(content || {}),
      Level: level
    });
  } catch (auditEx) {
    console.error("EmptyDatabaseReleaseAudit", auditEx && auditEx.message ? auditEx.message : auditEx);
  }
}

var currentUser = V8.CurrentUser || {};
var currentLevel = parseInt(currentUser.Level || 0, 10);
if (!currentUser.Id || isNaN(currentLevel) || currentLevel < 9999) {
  return {
    Code: 0,
    Msg: "权限不足：仅 iTdos 超级管理员可制作主库空数据库。"
