  V8.Param.TaskId
);
var baseParam = {
  OsClient: V8.OsClient,
  CurrentUser: currentUser,
  _BackgroundTaskId: backgroundTaskId
};

var checkpoint = V8.Param._BackgroundTaskCheckpoint || {};
var phase = text(checkpoint.Phase || "Prepare");
