/*
 * V8 ApiEngine
 * ApiEngineKey: admin_create_empty_saas_tenant
 * Version: v1.0.4
 * Function:
 * - SaaS 引擎超级管理员原子创建 SaaS 租户；支持官方标准空库或当前主租户 HDFS 私有目录中的单 SQL ZIP；后端全程保管连接串并负责分布式租约、初始化和补偿回滚。
 */

function toText(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}

function toBool(value) {
  return value === true || value === 1 || toText(value).toLowerCase() === 'true';
}

var backgroundTaskId = toText(V8.Param._BackgroundTaskId || V8.Param.BackgroundTaskId || V8.Param.TaskId);
var totalSteps = 10;

function report(current, msg) {
  if (!backgroundTaskId || !V8.Method || typeof V8.Method.UpdateBackgroundTask !== 'function') return;
  V8.Method.UpdateBackgroundTask({
    _BackgroundTaskId: backgroundTaskId,
    Current: current,
    Total: totalSteps,
    Progress: Math.floor(current * 100 / totalSteps),
    Msg: msg,
    Message: msg
  });
}

function fail(current, msg, data) {
  report(current, msg);
  return { Code: 0, Msg: msg, Data: data || null };
}

var currentUser = V8.CurrentUser || {};
var currentLevel = parseInt(currentUser.Level || 0, 10);
if (isNaN(currentLevel) || currentLevel < 9999) {
  return fail(1, '权限不足：只有主租户超级管理员才能创建 SaaS 租户。');
}

var tenantKey = toText(V8.Param.TenantKey || V8.Param.Key || V8.Param.OsClient);
var systemName = toText(V8.Param.SystemName || V8.Param.ClientName || V8.Param.Name);
var adminPassword = toText(V8.Param.AdminPassword || V8.Param.Password);
var osClientType = toText(V8.Param.OsClientType || 'Product');
var osClientNetwork = toText(V8.Param.OsClientNetwork || 'Internal');
var domainName = toText(V8.Param.DomainName || (tenantKey ? tenantKey + '.microi.net' : ''));
var ownerPhone = toText(V8.Param.OwnerPhone || V8.Param.Phone);
var dbType = toText(V8.Param.DbType || 'MySql');
var databaseSource = toText(V8.Param.DatabaseSource || 'OfficialEmpty');
var databaseZipPath = toText(V8.Param.DatabaseZipPath || V8.Param.SqlZipPath);
var databaseZipName = toText(V8.Param.DatabaseZipName || V8.Param.SqlZipName);
var validateOnly = toBool(V8.Param.ValidateOnly);

report(1, '正在校验租户参数');

if (!tenantKey) return fail(1, 'OsClient 不能为空。');
if (!/^[A-Za-z][A-Za-z0-9_-]*$/.test(tenantKey)) {
  return fail(1, 'OsClient 必须以英文字母开头，且只能包含英文字母、数字、-、_。');
}
if (!systemName) return fail(1, '系统名称不能为空。');
if (!adminPassword || adminPassword.length < 6) {
  return fail(1, 'admin 密码不能为空，且长度不能少于 6 位。');
}
if (!/^[A-Za-z][A-Za-z0-9_-]*$/.test(osClientType)) {
  return fail(1, 'OsClientType 格式不正确。');
}
if (!osClientNetwork || osClientNetwork.length > 50 || !/^[A-Za-z][A-Za-z0-9_.-]*$/.test(osClientNetwork)) {
  return fail(1, 'OsClientNetwork 不能为空，且只能包含英文字母、数字、-、_、.。');
}
if (!/^[A-Za-z0-9.-]+$/.test(domainName) || domainName.indexOf('..') >= 0) {
  return fail(1, '域名格式不正确，请只填写域名，不要包含协议或路径。');
}
if (dbType !== 'MySql') return fail(1, '当前 SaaS 租户开通能力仅支持 MySql。');

var useCustomZip = databaseSource === 'CustomZip' || !!databaseZipPath;
if (useCustomZip) {
  if (!databaseZipPath) return fail(1, '请选择并上传数据库 ZIP 包。');
  if (!databaseZipName || !/\.zip$/i.test(databaseZipName)) {
    return fail(1, '数据库包必须是 .zip 文件。');
  }
}

if (!V8.Method || typeof V8.Method.ProvisionAdminTenant !== 'function') {
  return fail(1, '当前后端尚未包含安全原子开通能力 V8.Method.ProvisionAdminTenant，请先升级并重启 Microi.Server。');
}
if (!V8.EncryptHelper || typeof V8.EncryptHelper.DESEncode !== 'function') {
  return fail(1, '当前后端缺少 admin 密码加密能力。');
}

if (validateOnly) {
  return {
    Code: 1,
    Msg: '参数与安全原子开通能力校验通过。',
    Data: {
      OsClient: tenantKey,
      SystemName: systemName,
      OsClientType: osClientType,
      OsClientNetwork: osClientNetwork,
      DomainName: domainName,
      DbType: dbType,
      DatabaseSource: useCustomZip ? 'CustomZip' : 'OfficialEmpty',
      ValidateOnly: true
    }
  };
}

report(2, useCustomZip ? '正在校验并还原数据库 ZIP' : '正在获取并导入官方标准空库');
var encryptedPassword = V8.EncryptHelper.DESEncode(adminPassword);
var provisionResult;
try {
  provisionResult = V8.Method.ProvisionAdminTenant({
    TenantKey: tenantKey,
    SystemName: systemName,
    OwnerPhone: ownerPhone,
    UserName: '管理员',
    EncryptedPwd: encryptedPassword,
    OsClientType: osClientType,
    OsClientNetwork: osClientNetwork,
    DomainName: domainName,
    DatabaseZipPath: useCustomZip ? databaseZipPath : '',
    DatabaseZipName: useCustomZip ? databaseZipName : ''
  });
} catch (ex) {
  return fail(9, '创建 SaaS 租户异常：' + ex.message);
}
if (!provisionResult || provisionResult.Code !== 1) {
  return fail(9, provisionResult && provisionResult.Msg ? provisionResult.Msg : '创建 SaaS 租户失败。', provisionResult);
}

report(10, 'SaaS 租户创建成功');
return {
  Code: 1,
  Msg: provisionResult.Msg || 'SaaS 租户创建成功。',
  Data: provisionResult.Data,
  DataAppend: provisionResult.DataAppend || {}
};

/*
 * V8 ApiEngine
 * ApiEngineKey: clear-saas-engine-cache
 * Version: v1.0.0
 * Function:
 * - 清除指定 SaaS 租户缓存并重载租户配置。
 */

var target = V8.Param.OsClientValue || V8.Param.TargetOsClient || V8.Param.OsClientKey || '';
if (!target && V8.Form && V8.Form.OsClient) {
  target = V8.Form.OsClient;
}
target = (target || '').toString().trim();
if (!target) {
  return { Code: 0, Msg: 'OsClient不能为空！' };
}

var clearResult = null;
try {
  if (V8.Method.ClearTenantCache) {
    clearResult = V8.Method.ClearTenantCache(target);
  }
} catch (clearEx) {
  clearResult = { Code: 0, Msg: clearEx && clearEx.message ? clearEx.message : clearEx.toString() };
}

var reloadResult = null;
try {
  reloadResult = V8.Method.ReloadOsClient(target);
} catch (reloadEx) {
  reloadResult = { Code: 0, Msg: reloadEx && reloadEx.message ? reloadEx.message : reloadEx.toString() };
