var ok = (clearResult && clearResult.Code == 1) || (reloadResult && reloadResult.Code == 1);
return {
  Code: ok ? 1 : 0,
  Msg: ok ? ('租户[' + target + ']缓存已清除并已重载。') : ('租户[' + target + ']缓存清除或重载失败。'),
  Data: {
    OsClient: target,
    ClearResult: clearResult,
    ReloadResult: reloadResult
  }
};

if(!V8.Param.Id || !V8.Param.OsClientValue || !V8.Param.OsClientType || !V8.Param.OsClientNetwork){
  return { Code : 1, Msg : '参数错误！' };
}
//获取源数据
var saasEngineResult = V8.FormEngine.GetFormData('Sys_OsClients', {
  Id : V8.Param.Id
});
if(saasEngineResult.Code != 1){
  return saasEngineResult;
}
var saasEngine = saasEngineResult.Data;
saasEngine.Id = '';
saasEngine.OsClient = V8.Param.OsClientValue;
saasEngine.OsClientType = V8.Param.OsClientType;
saasEngine.OsClientNetwork = V8.Param.OsClientNetwork;
var result = V8.FormEngine.AddFormData('Sys_OsClients', {
  _FormData : {
    ...saasEngine
  }
});
result.DataAppend = {
  // saasEngine : saasEngine
};
return result;
